import {
  createPagination,
  type Pagination as PaginationController,
  type PaginationItem as PaginationEntry,
  type PaginationOptions,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createContext, For, merge, untrack, useContext } from "solid-js";

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** What `render` gets: the props of the part, `data-part` and the caller's class merged in. */
export interface PaginationPartProps extends PartProps, Renderable<PaginationPartProps, void> {}

/** A part that carries nothing of its own: the list, a gap, the status text. */
export interface PaginationSectionProps extends PaginationPartProps {}

export interface PaginationProps extends PaginationOptions, Renderable<PaginationPartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
  /** The primitive, once: a page that reads the page list itself. */
  readonly onReady?: (pagination: PaginationController) => void;
}

/** One entry of the list: the page it shows; a gap is `PaginationEllipsis`. */
export interface PaginationItemProps extends Renderable<PaginationPartProps, void> {
  readonly page: number;
  readonly class?: string;
  readonly children?: JSX.Element;
}

/** A page control: `PaginationLink` for a page, the two arrow names for the ends. */
export interface PaginationLinkProps extends Renderable<PaginationPartProps, void> {
  readonly page: number;
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface PaginationEndProps extends Renderable<PaginationPartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

const PaginationContext = createContext<{ readonly pagination: PaginationController }>();

const nav = css.cn(
  css.display("flex"),
  css.flexWrap("wrap"),
  css.alignItems("center"),
  css.gap(t.space._3),
);

const list = css.cn(
  css.display("flex"),
  css.flexWrap("wrap"),
  css.alignItems("center"),
  css.gap(t.space._1),
  css.margin("0"),
  css.padding("0"),
  css.listStyle("none"),
);

const box = css.cn(css.display("flex"));

// A target is 24 CSS px square at AA (WCAG 2.2, 2.5.8): the box, not the text, is what a pointer has to hit. The current
// page is painted from its `aria-current`, so the skin keeps no copy of it, and an end that is out of range is painted
// disabled while staying in place and in the tab order, as the primitive asks.
const control = css.cn(
  css.display("inline-flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.boxSizing("border-box"),
  css.minWidth(t.space._6),
  css.minHeight(t.space._6),
  css.padding(t.space._1, t.space._2),
  css.border("1px solid", "transparent"),
  css.borderRadius(t.radius.sm),
  css.bg("transparent"),
  css.color(t.color.text),
  css.fontSize(t.font.size),
  css.textDecoration("none"),
  css.cursor("pointer"),
  css.hover(css.bg(t.color.buttonBackground)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
  css.attr("aria-current", "page")(
    css.bg(t.color.highlight),
    css.color(t.color.onHighlight),
    css.fontWeight("500"),
  ),
  css.attr("aria-current", "page")(css.hover(css.bg(t.color.highlight))),
  css.attr("aria-disabled", "true")(css.color(t.color.textDisabled), css.cursor("not-allowed")),
);

const ellipsis = css.cn(
  css.display("inline-flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.minWidth(t.space._6),
  css.color(t.color.muted),
  css.userSelect("none"),
);

const status = css.cn(css.margin("0"), css.fontSize(t.font.sizeSm), css.color(t.color.muted));

/**
 * Pagination: `createPagination` owns the page list, the elided runs, the ends and the announced count; this skin paints
 * the current page from `aria-current` and gives every target its 24 px square.
 *
 * `Pagination` is the nav landmark; `PaginationContent` is the list and, without children, its ordinary composition —
 * previous, the pages and their elided runs, next. The parts are exported for a caller that wants another order; a gap is
 * `PaginationEllipsis`, never a control.
 *
 * A page control is an `<a>` when `hrefFor` gives it an address (so it works without JS) and a `<button>` otherwise.
 */
export const Pagination = (props: PaginationProps): JSX.Element => {
  const pagination = createPagination({
    get page() {
      return props.page;
    },
    get pageCount() {
      return props.pageCount;
    },
    get siblings() {
      return props.siblings;
    },
    get boundaries() {
      return props.boundaries;
    },
    get hrefFor() {
      return props.hrefFor;
    },
    get disabled() {
      return props.disabled;
    },
    get labels() {
      return props.labels;
    },
    get onPageChange() {
      return props.onPageChange;
    },
  });
  untrack(() => props.onReady)?.(pagination);
  const merged = merge(pagination.navProps, () => ({
    "data-part": "pagination",
    get class() {
      return css.cn(nav, props.class);
    },
  }));
  return (
    <PaginationContext value={{ pagination }}>
      {renderPart(props, merged, undefined, (part) => (
        <nav {...part}>{props.children}</nav>
      ))}
    </PaginationContext>
  );
};

/** The list: a `role="list"`, and without children the pages, their gaps and the two ends in order. */
export const PaginationContent = (props: PaginationSectionProps): JSX.Element => {
  const { pagination } = useContext(PaginationContext);
  return renderPart(
    props,
    merge(pagination.listProps, {
      "data-part": "pagination-list",
      get class() {
        return css.cn(list, props.class);
      },
    }),
    undefined,
    (part) => (
      <ul {...part}>
        {props.children ?? (
          <>
            <li class={box}>
              <PaginationPrevious />
            </li>
            <For each={pagination.items()}>
              {(item: PaginationEntry) =>
                item.kind === "gap" ? (
                  <PaginationEllipsis />
                ) : (
                  <PaginationItem page={item.page}>
                    <PaginationLink page={item.page} />
                  </PaginationItem>
                )
              }
            </For>
            <li class={box}>
              <PaginationNext />
            </li>
          </>
        )}
      </ul>
    ),
  );
};

/** One page of the list: the current-page mark comes from the primitive, on the item and on its control. */
export const PaginationItem = (props: PaginationItemProps): JSX.Element => {
  const { pagination } = useContext(PaginationContext);
  return renderPart(
    props,
    merge(pagination.itemProps(props.page), {
      "data-part": "pagination-item",
      get class() {
        return css.cn(box, props.class);
      },
    }),
    undefined,
    (part) => <li {...part}>{props.children}</li>,
  );
};

/** The element a control is: the caller's `render`, else an anchor when it has an address and a button when it does not. */
const renderControl = (
  props: Renderable<PaginationPartProps, void>,
  merged: PartProps,
  href: string | undefined,
  children: JSX.Element,
): JSX.Element =>
  renderPart(props, merged, undefined, (part) =>
    href === undefined ? (
      <button {...part} type="button">
        {children}
      </button>
    ) : (
      <a {...part}>{children}</a>
    ),
  );

/**
 * A page's control: an anchor when the primitive gives it an `href`, a button otherwise, so a keyboard reaches it either
 * way. The label is the one the primitive announces.
 */
export const PaginationLink = (props: PaginationLinkProps): JSX.Element => {
  const { pagination } = useContext(PaginationContext);
  const link = pagination.linkProps(props.page);
  return renderControl(
    props,
    merge(link, {
      "data-part": "pagination-link",
      get class() {
        return css.cn(control, props.class);
      },
    }),
    link.href,
    props.children ?? props.page,
  );
};

/** The previous page: kept in place at the first page and painted disabled there. */
export const PaginationPrevious = (props: PaginationEndProps): JSX.Element => {
  const { pagination } = useContext(PaginationContext);
  return renderControl(
    props,
    merge(() => pagination.previousProps, {
      "data-part": "pagination-previous",
      get class() {
        return css.cn(control, props.class);
      },
    }),
    pagination.previousProps.href,
    props.children ?? "Previous",
  );
};

/** The next page: kept in place at the last page and painted disabled there. */
export const PaginationNext = (props: PaginationEndProps): JSX.Element => {
  const { pagination } = useContext(PaginationContext);
  return renderControl(
    props,
    merge(() => pagination.nextProps, {
      "data-part": "pagination-next",
      get class() {
        return css.cn(control, props.class);
      },
    }),
    pagination.nextProps.href,
    props.children ?? "Next",
  );
};

/** A run of pages the list elides: text, not a control, and hidden from a screen reader that hears the count. */
export const PaginationEllipsis = (props: PaginationPartProps): JSX.Element =>
  renderPart(
    props,
    {
      "data-part": "pagination-gap",
      get class() {
        return css.cn(box, ellipsis, props.class);
      },
    },
    undefined,
    (part) => (
      <li {...part}>
        <span aria-hidden="true">…</span>
      </li>
    ),
  );

/** The count, announced once here rather than in every control. */
export const PaginationStatus = (props: PaginationSectionProps): JSX.Element => {
  const { pagination } = useContext(PaginationContext);
  return renderPart(
    props,
    merge(pagination.statusProps, {
      "data-part": "pagination-status",
      get class() {
        return css.cn(status, props.class);
      },
    }),
    undefined,
    (part) => <p {...part}>{props.children ?? pagination.status()}</p>,
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { createSignal } from "solid-js";
import { render } from "@solidjs/web";
import { describe, expect, it } from "vite-plus/test";
import { Pagination, PaginationContent, PaginationStatus } from "./pagination.tsx";

// Solid 2 delivers events through its delegated listener on a later turn.
const tick = () => new Promise((resolve) => setTimeout(resolve, 20));

const mountPagination = (options: { page: number; pageCount: number }) => {
  const root = document.createElement("div");
  document.body.append(root);
  const [page, setPage] = createSignal(options.page);
  const dispose = render(
    () => (
      <Pagination
        page={page()}
        pageCount={options.pageCount}
        onPageChange={setPage}
        labels={{ nav: "Issue pages" }}
      >
        <PaginationContent />
        <PaginationStatus />
      </Pagination>
    ),
    root,
  );
  return {
    root,
    page,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

const current = (root: HTMLElement): HTMLElement | null =>
  root.querySelector<HTMLElement>('[data-part="pagination-link"][aria-current="page"]');
const links = (root: HTMLElement): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="pagination-link"]'),
];
const byText = (root: HTMLElement, text: string): HTMLElement | undefined =>
  links(root).find((link) => link.textContent === text);

describe("Pagination skin", () => {
  it("marks the current page aria-current and paints it, and leaves the others plain", () => {
    const { root, dispose } = mountPagination({ page: 2, pageCount: 5 });
    expect(
      root.querySelector<HTMLElement>('[data-part="pagination"]')?.getAttribute("aria-label"),
    ).toBe("Issue pages");
    const marked = current(root);
    expect(marked?.textContent).toBe("2");
    expect(root.querySelectorAll('[data-part="pagination-link"][aria-current="page"]').length).toBe(
      1,
    );
    // painted from the attribute: the current page is bolder and on the highlight
    expect(getComputedStyle(marked as HTMLElement).fontWeight).toBe("500");
    expect(getComputedStyle(marked as HTMLElement).backgroundColor).not.toBe(
      getComputedStyle(byText(root, "3") as HTMLElement).backgroundColor,
    );
    expect(getComputedStyle(byText(root, "3") as HTMLElement).fontWeight).not.toBe("500");
    dispose();
  });

  it("moves the current page with next and previous, and keeps the ends in place when disabled", async () => {
    const { root, page, dispose } = mountPagination({ page: 1, pageCount: 5 });
    const previous = root.querySelector<HTMLElement>('[data-part="pagination-previous"]');
    expect(previous?.getAttribute("aria-disabled")).toBe("true");
    expect(getComputedStyle(previous as HTMLElement).cursor).toBe("not-allowed");

    root.querySelector<HTMLElement>('[data-part="pagination-next"]')?.click();
    await tick();
    expect(page()).toBe(2);
    expect(current(root)?.textContent).toBe("2");
    expect(root.querySelector('[data-part="pagination-status"]')?.textContent).toBe("Page 2 of 5");
    expect(previous?.getAttribute("aria-disabled")).toBeNull();

    previous?.click();
    await tick();
    expect(page()).toBe(1);
    expect(current(root)?.textContent).toBe("1");
    // the control is still there at the first page: the primitive keeps the ends, it does not remove them
    expect(previous?.isConnected).toBe(true);
    dispose();
  });

  it("an ellipsis is a gap, not a control", () => {
    const { root, dispose } = mountPagination({ page: 6, pageCount: 12 });
    const gaps = [...root.querySelectorAll<HTMLElement>('[data-part="pagination-gap"]')];
    expect(gaps.length).toBe(2);
    for (const gap of gaps) {
      expect(gap.querySelector("a, button")).toBeNull();
      expect(gap.querySelector('[aria-hidden="true"]')?.textContent).toBe("…");
      expect(gap.hasAttribute("tabindex")).toBe(false);
    }
    const shown = links(root).map((link) => link.textContent);
    expect(shown).toEqual(["1", "5", "6", "7", "12"]);
    dispose();
  });

  it("announces the count once, in the primitive's status region", () => {
    const { root, dispose } = mountPagination({ page: 2, pageCount: 9 });
    const status = root.querySelector<HTMLElement>('[data-part="pagination-status"]');
    expect(status?.getAttribute("role")).toBe("status");
    expect(status?.getAttribute("aria-live")).toBe("polite");
    expect(status?.textContent).toBe("Page 2 of 9");
    expect(root.querySelectorAll('[role="status"]').length).toBe(1);
    dispose();
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
